{
  "findings": [
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent can turn off collaborative tools if students are not using them responsibly.",
      "stance": "mitigation",
      "quote": "But if the class isn't using the tools responsibly, a teacher or administrator can turn them all off."
    },
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "An administrator sets up Classroom and can turn features on or off for the entire school.",
      "stance": "neutral",
      "quote": "An administrator, often the school's information technology manager, sets up Classroom for the entire school. That person is in charge of all the features included in the service, including Gmail, Google Maps, and Drive -- and can turn them on or off."
    },
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "If Gmail is enabled, teachers can email students, turn off email notifications, and mute people.",
      "stance": "mitigation",
      "quote": "If Gmail is enabled, for example, teachers can email their students, turn off email notifications, and mute people."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "Logging in with a school account protects kids from some data collection beyond what is necessary for educational purposes.",
      "stance": "mitigation",
      "quote": "Logging in with a school account, rather than a personal Gmail account, protects kids from some data collection because education accounts can't be tracked or mined for data (beyond what's necessary for educational purposes)."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "If the school administrator enables Additional Services like YouTube and Maps, Google may collect data on those apps as it would for consumer apps.",
      "stance": "risk",
      "quote": "However, if the school's administrator enables Additional Services, such as YouTube and Maps, Google may collect data on those apps as it would for any of its other consumer apps."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "Third-party developers used for Classroom could collect information from kids and profile or target them using that data.",
      "stance": "risk",
      "quote": "Although Google doesn't share or sell student data to partners, and it vets the developers it uses for Classroom, those third parties could collect information from your kid, then profile and target them using that data."
    },
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "Google Classroom meets minimum requirements for protecting students' privacy according to Common Sense Media.",
      "stance": "mitigation",
      "quote": "Google Classroom gets a 'pass' rating from its Common Sense privacy evaluation, which means it meets our minimum requirements for protecting students' privacy."
    }
  ]
}
